import{_ as t,o as a,c as i,a2 as n}from"./chunks/framework.BXzK3EA4.js";const m=JSON.parse('{"title":"Filtered Seeds","description":"","frontmatter":{},"headers":[],"relativePath":"gameplay/seed.md","filePath":"gameplay/seed.md","lastUpdated":1788364293000}'),l={name:"gameplay/seed.md"};function r(s,e,o,d,h,u){return a(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="filtered-seeds" tabindex="-1">Filtered Seeds <a class="header-anchor" href="#filtered-seeds" aria-label="Permalink to &quot;Filtered Seeds&quot;">​</a></h1><h2 id="explanation" tabindex="-1">Explanation <a class="header-anchor" href="#explanation" aria-label="Permalink to &quot;Explanation&quot;">​</a></h2><p>MCSR Ranked uses its own Seed Filter to select vanilla seeds which satisfy certain conditions.</p><ul><li>In Ranked and Casual modes, filtered seeds are used in all matches.</li><li>In Private rooms, filtered seeds are used by default, but can be turned off by disabling the &quot;Use Filtered Seed&quot; match rule.</li></ul><p>For more efficient filtering and usability, the overworld and nether are filtered via independent seeds. Therefore, strategies that can infer some RNG in the Nether, such as the Divine Travel strategy, will not work.</p><h2 id="seed-type-distribution" tabindex="-1">Seed Type Distribution <a class="header-anchor" href="#seed-type-distribution" aria-label="Permalink to &quot;Seed Type Distribution&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Elo*</th><th style="text-align:center;">Village</th><th style="text-align:center;">Shipwreck</th><th style="text-align:center;">Desert Temple</th><th style="text-align:center;">Ruined Portal</th><th style="text-align:center;">Buried Treasure</th></tr></thead><tbody><tr><td style="text-align:center;">0 ~ 599</td><td style="text-align:center;">55%</td><td style="text-align:center;">15%</td><td style="text-align:center;">30%</td><td style="text-align:center;">0%</td><td style="text-align:center;">0%</td></tr><tr><td style="text-align:center;">600 ~ 1199</td><td style="text-align:center;">30%</td><td style="text-align:center;">25%</td><td style="text-align:center;">25%</td><td style="text-align:center;">20%</td><td style="text-align:center;">0%</td></tr><tr><td style="text-align:center;">1200+</td><td style="text-align:center;">20%</td><td style="text-align:center;">20%</td><td style="text-align:center;">20%</td><td style="text-align:center;">20%</td><td style="text-align:center;">20%</td></tr></tbody></table><p>*Based on the lowest Elo of all players in the match.</p><p>In Private Rooms, the seed type distribution is the same as in the 1200+ Elo range.</p><h2 id="overworld-types" tabindex="-1">Overworld Types <a class="header-anchor" href="#overworld-types" aria-label="Permalink to &quot;Overworld Types&quot;">​</a></h2><h3 id="village" tabindex="-1">Village <a class="header-anchor" href="#village" aria-label="Permalink to &quot;Village&quot;">​</a></h3><ul><li>Spawns within 7 chunks</li><li>Contains a guaranteed Blacksmith*</li><li>At least 7 Iron (or 4 Iron + 3 Diamonds) (including golem) with food in chests or haybales</li><li>Iron Golem always drops 4 Iron (never 3 or 5)</li><li>A River Biome is guaranteed within 6 chunks of the center of the village</li><li>3 lava pools are guaranteed near the Village OR the Blacksmith contains 8+ Obsidian for an enter with Blacksmith lava <ul><li>Artificial lava pools look similar to vanilla and are the 3 guaranteed ones! There may be more vanilla lava pools but the artificial ones are guaranteed.</li></ul></li><li>Taiga villages always have 10+ Obsidian enters (lava pools do still exist)</li></ul><p>*The guaranteed Blacksmith is usually a Weaponsmith, but can instead be a Toolsmith in Desert and Taiga Villages or an Armorer in Snowy Villages.</p><h3 id="shipwreck" tabindex="-1">Shipwreck <a class="header-anchor" href="#shipwreck" aria-label="Permalink to &quot;Shipwreck&quot;">​</a></h3><ul><li>Spawns within 4 chunks</li><li>At least 7 Iron (or 4 Iron + 3 Diamonds) and some food in food chest</li><li>Suspicious stew CANNOT give poison</li><li>No other shipwrecks, buried treasures, or irrelevant block entities near spawn (e.g. dungeons)</li><li>Shipwreck chests will not be buried [mostly...]</li><li>2 Magma Ravines are guaranteed within 10 chunks of the Shipwreck <ul><li>Filtered Magma Ravines are not generated in Frozen Ocean Biomes</li></ul></li></ul><h3 id="desert-temple" tabindex="-1">Desert Temple <a class="header-anchor" href="#desert-temple" aria-label="Permalink to &quot;Desert Temple&quot;">​</a></h3><ul><li>Spawns within 5 chunks</li><li>At least 7 Iron (or 4 Iron + 3 Diamonds)</li><li>Some food in chests (😋 rotten flesh)</li><li>Nearby access to wood [mostly...]</li><li>A River biome is guaranteed within 6 chunks of the Desert Temple</li><li>3 lava pools are guaranteed near the temple <ul><li>Artificial lava pools look similar to vanilla and are the 3 guaranteed ones! There may be more vanilla lava pools but the artificial ones are guaranteed.</li></ul></li></ul><h3 id="ruined-portal" tabindex="-1">Ruined Portal <a class="header-anchor" href="#ruined-portal" aria-label="Permalink to &quot;Ruined Portal&quot;">​</a></h3><ul><li>Spawns within 3 chunks</li><li>Guaranteed at least 18 iron nuggets, excluding those needed to make the Bucket or Flint and Steel if needed <ul><li>There&#39;s a chance that there won’t be enough Iron for an Iron Pickaxe</li></ul></li><li>Food in chest or animals within 5 chunks with a Flint and Steel / Fire Aspect Sword</li><li>A light is guaranteed! (e.g. Flint and Steel, Fire Charge, Flint and extra iron nuggets)</li><li>Enterable with Obsidian or Bucket (80/20)</li></ul><h3 id="buried-treasure" tabindex="-1">Buried Treasure <a class="header-anchor" href="#buried-treasure" aria-label="Permalink to &quot;Buried Treasure&quot;">​</a></h3><ul><li>Spawns within 5 chunks</li><li>At least 7 Iron (or 4 Iron + 3 Diamonds)</li><li>No other buried treasures, shipwrecks, or irrelevant block entities near spawn (e.g. dungeons)</li><li>2 Magma Ravines are guaranteed within 10 chunks of the Buried Treasure <ul><li>Filtered Magma Ravines are not generated in Frozen Ocean Biomes</li></ul></li></ul><h2 id="nether-requirements" tabindex="-1">Nether Requirements <a class="header-anchor" href="#nether-requirements" aria-label="Permalink to &quot;Nether Requirements&quot;">​</a></h2><h3 id="bastion-remnant" tabindex="-1">Bastion Remnant <a class="header-anchor" href="#bastion-remnant" aria-label="Permalink to &quot;Bastion Remnant&quot;">​</a></h3><ul><li>Closest Bastion Remnant is always the intended Bastion Remnant, it will be at least 10 chunks closer than any other Bastion Remnant to 0,0*</li><li>Intended Bastion Remnant is within 14 chunks of 0,0*</li><li>Open terrain check from approximate nether entry to the Bastion Remnant</li><li>Intended Bastion Remnant always has 3+ Iron and 5+ Obsidian somewhere in the ramparts&#39; chests (or any chest for housing)</li><li>Stables Bastion Remnant has at least 1 good gap</li></ul><p>*This means that the X coordinate is 0 and Z coordinate is 0. (0, 0)</p><h3 id="fortress" tabindex="-1">Fortress <a class="header-anchor" href="#fortress" aria-label="Permalink to &quot;Fortress&quot;">​</a></h3><ul><li>Fortress origin is within 16 chunks of the intended Bastion Remnant</li><li>Open terrain check from the Bastion Remnant to the Fortress</li></ul><h2 id="the-end" tabindex="-1">The End <a class="header-anchor" href="#the-end" aria-label="Permalink to &quot;The End&quot;">​</a></h2><p>For the most part, The End uses the same seed as Overworld seed. And there is no filtering condition, so any seed can be selected regardless of its End generation.</p><h2 id="rng" tabindex="-1">RNG <a class="header-anchor" href="#rng" aria-label="Permalink to &quot;RNG&quot;">​</a></h2><p>For the most part, RNG seed uses the same seed as Overworld seed. Check this <a href="./rng">document</a></p>',31)])])}const p=t(l,[["render",r]]);export{m as __pageData,p as default};
